var AccountOverview=function(n){var t={initialize:function(){t.initEvent();t.renderView("Summary")},initEvent:function(){n("#account-overview-menu").on("click",".account-overview-menu",function(){var i=n(this).data("name");t.renderView(i)})},activeMenu:function(t){var i="active";n(".account-overview-menu").removeClass(i);n("#menu"+t).addClass(i)},renderView:function(i){t.activeMenu(i);n.ajax({type:"POST",dataType:"html",cache:!1,data:JSON.stringify(null),url:Site.resolveRelativeUrl("UserPanel/AccountOverView/"+i),contentType:"application/json; charset=UTF-8",success:function(t){n("#account-overview-content").html(t)},beforeSend:function(){Site.showLoader()},complete:function(){Site.hideLoader()}})}};return t}(jQuery);AccountOverview.initialize();